'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import Link from 'next/link';
import { Activity, ArrowLeft, ArrowRight, Check, ChevronDown, CircleAlert, Clapperboard, Clock3, ExternalLink, FileUp, Film, LayoutDashboard, ListChecks, LoaderCircle, LogOut, Plus, RefreshCw, Search, Server, ShieldCheck, SlidersHorizontal, Trash2, X } from 'lucide-react';
import type { CatalogResponse, Episode, Job, Playlist, Source, Title, User } from '../../lib/types';
import AuthModal from '../../components/AuthModal';
import AdminTitlePicker from '../../components/AdminTitlePicker';
import AdminPlaylistCard from '../../components/AdminPlaylistCard';
import { playlistIssue, playlistRefresh } from '../../lib/playlist-presentation';
import { RequestError, requestJson } from '../../lib/client';
import '../../components/admin.css';

type Section = 'overview' | 'playlists' | 'catalog' | 'reviews' | 'activity';
interface Review { id: string; sourceId: string; titleId: string; candidateId: string | null; reason: string; status: string; createdAt: number; titleName: string; candidateName: string | null; }
interface Audit { id: string; actorId: string; action: string; entityId: string; createdAt: number; details: unknown; }
interface Overview { stats: Record<string, number | null>; playlists: Playlist[]; jobs: Job[]; reviews: Review[]; audit: Audit[]; worker?: { online: boolean; lastHeartbeat: number | null; unclaimedJobs: number }; }
interface ImportRow { id: number; name: string; url: string; content: string; fileName: string; }
const navigation: { id: Section; label: string; icon: typeof Film }[] = [{ id: 'overview', label: 'Overview', icon: LayoutDashboard }, { id: 'playlists', label: 'Playlists', icon: ListChecks }, { id: 'catalog', label: 'Catalog', icon: Clapperboard }, { id: 'reviews', label: 'Match review', icon: SlidersHorizontal }, { id: 'activity', label: 'Activity & jobs', icon: Activity }];
const date = (value?: number | null) => value ? new Date(value).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
async function api<T = Record<string, unknown>>(url: string, method = 'GET', body?: unknown): Promise<T> {
  return requestJson<T>(url, { method, ...(body !== undefined ? { body: JSON.stringify(body) } : {}) }, url === '/api/admin/playlists' && method === 'POST' ? 300_000 : url === '/api/admin/overview' ? 120_000 : 30_000);
}
function HealthBadge({ health }: { health: string }) { return <span className={`admin-health ${health}`}><span />{health === 'unknown' ? 'Awaiting check' : health}</span>; }
function ImportBadge({ playlist, job }: { playlist: Playlist; job?: Job }) {
  const refresh = playlistRefresh({ ...playlist, latestSyncJob: playlist.latestSyncJob || job });
  return <span className={`admin-health ${refresh.tone}`}><span />{refresh.label}</span>;
}
function PlaylistProgress({ playlist }: { playlist: Playlist }) {
  if (playlist.sourceCount === undefined) return null;
  return <small>{(playlist.visibleTitleCount ?? 0).toLocaleString()} unique titles visible{playlist.pendingSourceCount ? ' · Checking new streams' : ''}</small>;
}
function titleSources(title: Title): Source[] { return [...new Map([...(title.sources || []), ...(title.episodes?.flatMap(episode => episode.sources || []) || [])].map(source => [source.id, source])).values()]; }
function Empty({ children }: { children: React.ReactNode }) { return <div className="admin-empty"><Film size={30} /><p>{children}</p></div>; }
function Field({ label, children, wide }: { label: string; children: React.ReactNode; wide?: boolean }) { return <label className={`admin-field ${wide ? 'wide' : ''}`}><span>{label}</span>{children}</label>; }
function Dialog({ title, children, onClose, wide }: { title: string; children: React.ReactNode; onClose: () => void; wide?: boolean }) {
  const ref = useRef<HTMLDivElement>(null); const closeRef = useRef(onClose); closeRef.current = onClose;
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null; const overflow = document.body.style.overflow; document.body.style.overflow = 'hidden';
    ref.current?.querySelector<HTMLElement>('input,select,textarea,button')?.focus();
    const handler = (event: KeyboardEvent) => {
      if (event.key === 'Escape') closeRef.current();
      if (event.key !== 'Tab') return;
      const elements = ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]');
      if (!elements?.length) return;
      if (event.shiftKey && document.activeElement === elements[0]) { event.preventDefault(); elements[elements.length - 1].focus(); }
      else if (!event.shiftKey && document.activeElement === elements[elements.length - 1]) { event.preventDefault(); elements[0].focus(); }
    };
    document.addEventListener('keydown', handler);
    return () => { document.removeEventListener('keydown', handler); document.body.style.overflow = overflow; previous?.focus(); };
  }, []);
  return <div className="admin-overlay" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><div ref={ref} className={`admin-dialog ${wide ? 'large' : ''}`} role="dialog" aria-modal="true" aria-label={title}><div className="admin-dialog-title"><h2>{title}</h2><button className="admin-icon" onClick={onClose} aria-label="Close dialog"><X size={20} /></button></div>{children}</div></div>;
}

export default function AdminPage() {
  const [user, setUser] = useState<User | null>(null);
  const [checking, setChecking] = useState(true);
  const [authOpen, setAuthOpen] = useState(false);
  const [section, setSection] = useState<Section>('overview');
  const [playlistSearch, setPlaylistSearch] = useState('');
  const [playlistAttention, setPlaylistAttention] = useState(false);
  const [overview, setOverview] = useState<Overview | null>(null);
  const [catalog, setCatalog] = useState<CatalogResponse>({ titles: [], total: 0, genres: [] });
  const [query, setQuery] = useState('');
  const [type, setType] = useState('');
  const [availability, setAvailability] = useState('');
  const [page, setPage] = useState(1);
  const [catalogLoading, setCatalogLoading] = useState(false);
  const [error, setError] = useState('');
  const [overviewError, setOverviewError] = useState('');
  const [catalogError, setCatalogError] = useState('');
  const [toast, setToast] = useState('');
  const [pending, setPending] = useState<string | null>(null);
  const [importOpen, setImportOpen] = useState(false);
  const [playlistEdit, setPlaylistEdit] = useState<Playlist | null>(null);
  const [titleEdit, setTitleEdit] = useState<Title | null>(null);
  const [historyId, setHistoryId] = useState<string | null>(null);
  const [importJobs, setImportJobs] = useState<Record<string, string>>({});
  const overviewFlightRef = useRef<Promise<void> | null>(null);
  const overviewRevisionRef = useRef(0);
  const overviewQueuedRef = useRef(false);
  const overviewActiveRef = useRef(false);
  const catalogRevisionRef = useRef(0);
  const catalogControllerRef = useRef<AbortController | null>(null);
  const catalogParamsRef = useRef({ query, type, availability, page });
  catalogParamsRef.current = { query, type, availability, page };
  const allowed = user?.role === 'admin' || user?.role === 'editor';

  const resetAdminAccess = useCallback((reason: RequestError) => {
    overviewActiveRef.current = false; overviewQueuedRef.current = false; overviewRevisionRef.current++;
    catalogRevisionRef.current++; catalogControllerRef.current?.abort();
    setUser(null); setOverview(null); setCatalog({ titles: [], total: 0, genres: [] }); setCatalogLoading(false);
    setImportOpen(false); setPlaylistEdit(null); setTitleEdit(null); setHistoryId(null); setAuthOpen(false);
    setPending(null); setToast(''); setOverviewError(''); setCatalogError('');
    setError(reason.status === 401 ? 'Your session has ended. Sign in again to continue.' : 'Administrator access is no longer available. Sign in with an authorized account.');
    if (reason.status === 401) window.dispatchEvent(new CustomEvent('luma-auth', { detail: null }));
  }, []);

  const loadOverview = useCallback((): Promise<void> => {
    if (!overviewActiveRef.current) return Promise.resolve();
    if (overviewFlightRef.current) return overviewFlightRef.current;
    const revision = overviewRevisionRef.current; overviewQueuedRef.current = false;
    const request = api<Overview>('/api/admin/overview').then(data => { if (overviewActiveRef.current && revision === overviewRevisionRef.current) { setOverview(data); setOverviewError(''); } }).catch(reason => { if (!overviewActiveRef.current || revision !== overviewRevisionRef.current) return; if (reason instanceof RequestError && [401, 403].includes(reason.status)) resetAdminAccess(reason); else setOverviewError(reason instanceof Error ? reason.message : 'Could not load administration data.'); }).finally(() => {
      if (overviewFlightRef.current !== request) return;
      overviewFlightRef.current = null;
      if (overviewActiveRef.current && overviewQueuedRef.current) void loadOverview();
    });
    overviewFlightRef.current = request; return request;
  }, [resetAdminAccess]);
  const refreshAfterMutation = useCallback(async () => { overviewRevisionRef.current++; overviewQueuedRef.current = true; await loadOverview(); }, [loadOverview]);
  const loadCatalog = useCallback(async () => {
    if (!overviewActiveRef.current) return;
    const revision = ++catalogRevisionRef.current;
    catalogControllerRef.current?.abort();
    const controller = new AbortController(); catalogControllerRef.current = controller;
    const params = catalogParamsRef.current;
    setCatalogLoading(true);
    try {
      const result = await requestJson<CatalogResponse>(`/api/admin/catalog?q=${encodeURIComponent(params.query)}&type=${params.type}&availability=${params.availability}&page=${params.page}&limit=24`, { signal: controller.signal });
      if (overviewActiveRef.current && revision === catalogRevisionRef.current) { setCatalog(result); setCatalogError(''); }
    } catch (reason) {
      if (controller.signal.aborted || !overviewActiveRef.current || revision !== catalogRevisionRef.current) return;
      if (reason instanceof RequestError && [401, 403].includes(reason.status)) resetAdminAccess(reason);
      else setCatalogError(reason instanceof Error ? reason.message : 'Could not load the catalog.');
    } finally { if (revision === catalogRevisionRef.current) { catalogControllerRef.current = null; setCatalogLoading(false); } }
  }, [query, type, availability, page, resetAdminAccess]);

  useEffect(() => { api<{ user: User | null }>('/api/auth/me').then(data => setUser(data.user)).catch(reason => setError(reason.message)).finally(() => setChecking(false)); }, []);
  useEffect(() => { if (!allowed) return; overviewActiveRef.current = true; loadOverview(); const timer = setInterval(() => { if (document.visibilityState === 'visible') void loadOverview(); }, 10000); return () => { clearInterval(timer); overviewActiveRef.current = false; overviewQueuedRef.current = false; }; }, [allowed, loadOverview]);
  useEffect(() => { if (!allowed || section !== 'catalog') return; const timer = setTimeout(loadCatalog, 250); return () => { clearTimeout(timer); catalogRevisionRef.current++; catalogControllerRef.current?.abort(); }; }, [allowed, section, loadCatalog]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 4500); return () => clearTimeout(timer); }, [toast]);

  async function perform(key: string, request: () => Promise<unknown>, success: string) {
    setPending(key); setError('');
    try { await request(); setToast(success); await refreshAfterMutation(); if (section === 'catalog') await loadCatalog(); return true; }
    catch (reason) { if (reason instanceof RequestError && [401, 403].includes(reason.status)) resetAdminAccess(reason); else setError(reason instanceof Error ? reason.message : 'The change could not be saved.'); return false; }
    finally { setPending(null); }
  }
  async function logout() { setPending('logout'); setError(''); try { await api('/api/auth/logout', 'POST'); overviewActiveRef.current = false; overviewRevisionRef.current++; overviewQueuedRef.current = false; setUser(null); setOverview(null); window.dispatchEvent(new CustomEvent('luma-auth', { detail: null })); setToast('Signed out.'); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not sign out. Please try again.'); } finally { setPending(null); } }
  async function reviewClassification(review: Review) {
    setPending(review.id); setError('');
    try { const data = await api<CatalogResponse>(`/api/admin/catalog?q=${encodeURIComponent(review.titleName)}&limit=100`); const title = data.titles.find(value => value.id === review.titleId); if (!title) throw new Error('This title could not be found. Refresh the review queue and try again.'); setTitleEdit(title); }
    catch (reason) { setError(reason instanceof Error ? reason.message : 'Title metadata could not be loaded.'); }
    finally { setPending(null); }
  }

  if (checking) return <div className="admin-gate"><LoaderCircle className="spin" /><p>Checking your session…</p></div>;
  if (!allowed) return <main className="admin-gate"><Link href="/" className="admin-brand"><Film size={24} />lume<span>.</span></Link><div className="admin-gate-icon"><ShieldCheck size={34} /></div><div className="admin-eyebrow">LUME CONTROL ROOM</div><h1>{user ? 'Administrator access required.' : 'A little behind the scenes.'}</h1><p>{user ? 'Your account does not have permission to manage the catalog. Ask your administrator to grant the appropriate role.' : 'Sign in with an administrator or editor account to manage your catalog, authorized playlists, and stream health.'}</p>{!user && <button className="admin-button primary" onClick={() => setAuthOpen(true)}>Sign in <ArrowRight size={17} /></button>}<Link className="admin-link" href="/"><ArrowLeft size={15} /> Back to browsing</Link>{error && <p className="admin-error">{error}</p>}<AuthModal open={authOpen} onClose={() => setAuthOpen(false)} onAuthenticated={value => { setUser(value); setError(''); }} /></main>;

  const playlists = overview?.playlists || [];
  const attentionPlaylists = playlists.filter(playlist => playlistIssue(playlist) || playlist.reviewCount);
  const displayedPlaylists = playlists.filter(playlist => playlist.name.toLowerCase().includes(playlistSearch.trim().toLowerCase()) && (!playlistAttention || playlistIssue(playlist) || playlist.reviewCount));
  const reviews = overview?.reviews || [];
  const jobs = overview?.jobs || [];
  const stats = overview?.stats;
  const failed = jobs.filter(job => job.status === 'failed');
  return <div className="admin-shell">
    <aside className="admin-sidebar"><Link href="/" className="admin-brand"><Film size={23} />lume<span>.</span></Link><div className="admin-workspace"><span className="admin-workspace-icon"><ShieldCheck size={17} /></span><span>Control room<small>CONTENT OPERATIONS</small></span></div><div className="admin-nav-label">WORKSPACE</div><nav>{navigation.map(item => <button key={item.id} className={section === item.id ? 'active' : ''} onClick={() => setSection(item.id)}><item.icon size={18} /><span>{item.label}</span>{item.id === 'reviews' && reviews.length > 0 && <b>{reviews.length}</b>}</button>)}</nav><div className="admin-sidebar-foot"><div className={`admin-status-dot ${overview?.worker && !overview.worker.online ? 'offline' : ''}`} /><span>{overview?.worker ? overview.worker.online ? 'Processing service online' : 'Processing service offline' : 'Checking processing service'}</span><small>{overview?.worker?.lastHeartbeat ? `Last heartbeat: ${date(overview.worker.lastHeartbeat)}` : 'Imports and stream checks run in the background.'}</small><Link href="/">Open streaming site <ExternalLink size={13} /></Link></div></aside>
    <main className="admin-main"><header className="admin-topbar"><span>Workspace <span className="admin-breadcrumb">/</span> <b>{navigation.find(item => item.id === section)?.label}</b></span><div className="admin-user"><span className="admin-avatar">{user!.name.slice(0, 1).toUpperCase()}</span><div>{user!.name}<small>{user!.role}</small></div><button className="admin-icon" onClick={logout} aria-label="Sign out" disabled={pending === 'logout'}><LogOut size={17} /></button></div></header>
      <div className="admin-content"><div className="admin-page-heading"><div><div className="admin-eyebrow">THE BIG PICTURE</div><h1>{section === 'overview' ? 'A good day for great stories.' : section === 'playlists' ? 'Your playlist library.' : section === 'catalog' ? 'Curate the collection.' : section === 'reviews' ? 'A second pair of eyes.' : 'Every change, accounted for.'}</h1><p>{section === 'overview' ? 'Keep a pulse on your catalog and the streams behind it.' : section === 'playlists' ? 'See what viewers can watch, and keep each playlist up to date.' : section === 'catalog' ? 'Manage metadata, publication, episodes, and individual sources.' : section === 'reviews' ? 'Resolve uncertain title matches before combining streaming sources.' : 'Inspect background jobs, synchronization results, and administrative actions.'}</p></div>{(section === 'overview' || section === 'playlists') && <button className="admin-button primary" onClick={() => setImportOpen(true)}><Plus size={16} />Add playlist</button>}</div>
      {overview?.worker && !overview.worker.online && overview.worker.unclaimedJobs > 0 && <div className="admin-worker-warning" role="status"><CircleAlert size={21} /><div><strong>Imports are waiting for the processing service.</strong><p>{overview.worker.unclaimedJobs} queued jobs have not been claimed. Your playlists are saved, but importing and stream verification cannot finish while the worker is offline.</p><p>Restart the local app with <code>npm run dev</code> to launch its worker. For Docker deployments, start the worker service.</p><small>Last heartbeat: {date(overview.worker.lastHeartbeat)}</small></div><button className="admin-text-button" onClick={() => setSection('activity')}>View jobs <ArrowRight size={13} /></button></div>}
      {(error || overviewError || catalogError) && <div className="admin-error" role="alert"><CircleAlert size={17} /><span>{error || overviewError || catalogError}</span><button onClick={() => { setError(''); setOverviewError(''); setCatalogError(''); }} aria-label="Dismiss error"><X size={15} /></button></div>}
      {section === 'overview' && <>
        <div className="admin-metrics">{[{ label: 'Movies', key: 'movies', icon: Film }, { label: 'TV series', key: 'series', icon: Clapperboard }, { label: 'Verified sources', key: 'healthySources', icon: ShieldCheck }, { label: 'Need attention', key: 'brokenSources', icon: CircleAlert }].map(metric => <div className="admin-metric" key={metric.key}><div><span>{metric.label}</span><metric.icon size={17} /></div><strong>{stats ? (stats[metric.key] ?? '—').toLocaleString() : <span className="admin-skeleton" />}</strong><small>{metric.key === 'healthySources' ? 'Confirmed healthy by source checks' : metric.key === 'brokenSources' ? 'Sources confirmed unavailable' : metric.key === 'series' ? `${stats?.episodes ?? '—'} episodes in your catalog` : 'All published and hidden titles'}</small></div>)}</div>
        <div className="admin-summary"><span><Server size={15} /><b>{stats?.sources ?? '—'}</b> total sources</span><span><ListChecks size={15} /><b>{stats?.playlists ?? '—'}</b> playlists</span><span><Film size={15} /><b>{stats?.hiddenTitles ?? '—'}</b> hidden titles</span><span><Clock3 size={15} />Last sync <b>{date(stats?.lastSync)}</b></span><span>Next <b>{date(stats?.nextSync)}</b></span></div>
        <div className="admin-overview-grid"><section className="admin-panel"><div className="admin-panel-heading"><div><h2>Connected playlists</h2><p>The heartbeat of your collection.</p></div><button className="admin-text-button" onClick={() => setSection('playlists')}>Manage <ArrowRight size={14} /></button></div>{playlists.length ? <div className="admin-playlist-overview">{playlists.slice(0, 5).map(playlist => <div key={playlist.id}><span className="admin-small-icon"><ListChecks size={18} /></span><div className="admin-grow"><strong>{playlist.name}</strong><small>{playlist.entryCount.toLocaleString()} entries · every {playlist.intervalHours}h</small><PlaylistProgress playlist={playlist} /></div><ImportBadge playlist={playlist} job={jobs.find(job => job.id === importJobs[playlist.id])} /></div>)}</div> : <Empty>Add your first authorized playlist to grow the collection.</Empty>}</section><section className="admin-panel"><div className="admin-panel-heading"><div><h2>Recent jobs</h2><p>Real results from the background workers.</p></div><button className="admin-icon" onClick={loadOverview} aria-label="Refresh dashboard"><RefreshCw size={16} /></button></div>{jobs.length ? <div className="admin-job-list">{jobs.slice(0, 5).map(job => <div key={job.id}><span className={`admin-job-dot ${job.status}`} /><div className="admin-grow"><strong>{job.type.replaceAll('_', ' ')}</strong><small>{date(job.createdAt)}</small></div><span className={`admin-job-status ${job.status}`}>{job.status}</span></div>)}</div> : <Empty>No background jobs yet.</Empty>}</section></div>
        {failed.length > 0 && <section className="admin-panel admin-recent-errors"><div className="admin-panel-heading"><div><h2>Needs your attention</h2><p>Failed jobs keep their previous imported snapshot.</p></div><button className="admin-text-button" onClick={() => setSection('activity')}>Inspect jobs <ArrowRight size={14} /></button></div>{failed.slice(0, 3).map(job => <div className="admin-error-row" key={job.id}><CircleAlert size={16} /><div><strong>{job.type.replaceAll('_', ' ')}</strong><p>{job.error || 'No error details were recorded.'}</p></div><time>{date(job.createdAt)}</time></div>)}</section>}
        <div className="admin-note"><ShieldCheck size={18} /><div><strong>Availability is verified per source.</strong><p>A title is discoverable when at least one enabled source has passed its health check. Failed imports preserve existing metadata and watch progress.</p></div></div>
      </>}
      {section === 'playlists' && <section className="admin-playlists-section" aria-label="Playlist library">
        <div className="admin-playlists-toolbar">
          <div><h2>Connected playlists <span className="admin-count">{playlists.length}</span></h2><p>Saved content and the latest refresh, at a glance.</p></div>
          <button className="admin-button" onClick={loadOverview} aria-label="Refresh playlist statuses"><RefreshCw size={16} />Update status</button>
        </div>
        <div className="admin-playlist-filters"><label className="admin-search"><Search size={18} /><input value={playlistSearch} onChange={event => setPlaylistSearch(event.target.value)} placeholder="Find a playlist…" aria-label="Find a playlist" /></label><button className={playlistAttention ? 'admin-attention-filter active' : 'admin-attention-filter'} onClick={() => setPlaylistAttention(value => !value)} aria-pressed={playlistAttention}><CircleAlert size={15} />Needs attention <span>{attentionPlaylists.length}</span></button></div>
        <div className="admin-playlist-list">{displayedPlaylists.map(playlist => <AdminPlaylistCard key={playlist.id} playlist={playlist} pending={pending !== null} busy={pending === playlist.id} isAdmin={user?.role === 'admin'} workerOnline={overview?.worker?.online}
          onRefresh={() => { void perform(playlist.id, () => api(`/api/admin/playlists/${playlist.id}/sync`, 'POST'), 'Refresh requested. Follow its progress under Latest refresh.'); }}
          onReview={() => setSection('reviews')} onEdit={() => setPlaylistEdit(playlist)} onHistory={() => setHistoryId(playlist.id)}
          onToggle={() => { void perform(playlist.id, () => api(`/api/admin/playlists/${playlist.id}`, 'PATCH', { enabled: !playlist.enabled }), playlist.enabled ? 'Playlist disabled. Its titles are hidden from viewers.' : 'Playlist enabled.'); }}
          onDelete={() => { if (window.confirm(`Delete “${playlist.name}” and its imported sources? Other playlists and watch progress will be preserved.`)) void perform(playlist.id, () => api(`/api/admin/playlists/${playlist.id}`, 'DELETE'), 'Playlist deleted.'); }} />)}</div>
        {!overview ? <div className="admin-loading"><LoaderCircle className="spin" />Loading your playlists…</div> : !playlists.length ? <Empty>No playlists connected yet. Add a link or upload an M3U file to get started.</Empty> : !displayedPlaylists.length ? <Empty>No playlists match this view. Try another name or turn off the attention filter.</Empty> : null}
        <p className="admin-playlists-privacy"><ShieldCheck size={15} />Private playlist links and credentials stay on the server.</p>
      </section>}
      {section === 'catalog' && <>
        <div className="admin-filters"><label className="admin-search"><Search size={17} /><input value={query} onChange={event => { setQuery(event.target.value); setPage(1); }} placeholder="Search titles, cast, or genres…" aria-label="Search admin catalog" /></label><select value={type} onChange={event => { setType(event.target.value); setPage(1); }} aria-label="Filter content type"><option value="">All types</option><option value="movie">Movies</option><option value="series">TV series</option><option value="live">Live channels</option></select><select value={availability} onChange={event => { setAvailability(event.target.value); setPage(1); }} aria-label="Filter availability"><option value="">All availability</option><option value="available">Available</option><option value="hidden">Hidden / unavailable</option></select><span>{catalog.total} titles</span></div>
        <section className="admin-panel"><div className="admin-table-wrap"><table className="admin-table admin-catalog-table"><thead><tr><th>Title</th><th>Type / year</th><th>Sources</th><th>Published</th><th>Actions</th></tr></thead><tbody>{catalog.titles.map(title => <tr key={title.id}><td><div className="admin-title-cell">{title.poster ? <img src={title.poster} alt="" loading="lazy" /> : <span className="admin-poster-placeholder"><Film size={20} /></span>}<div><strong>{title.name}</strong><small>{title.genres.join(' · ') || 'No genres added'}</small></div></div></td><td className="capitalize">{title.type}<small>{title.year || 'Year unknown'}</small></td><td>{titleSources(title).length}<small>{titleSources(title).filter(source => source.health === 'healthy' && source.enabled).length} healthy</small></td><td><span className={`admin-published ${title.published ? 'yes' : ''}`}>{title.published ? 'Published' : 'Hidden'}</span></td><td><button className="admin-button compact" onClick={() => setTitleEdit(title)}>Manage <ArrowRight size={14} /></button></td></tr>)}</tbody></table></div>{catalogLoading && !catalog.titles.length ? <div className="admin-loading"><LoaderCircle className="spin" />Loading catalog…</div> : !catalog.titles.length && <Empty>No titles match these filters.</Empty>}<div className="admin-pagination"><span>Page {page} · {catalog.total} titles</span><div><button disabled={page === 1 || catalogLoading} onClick={() => setPage(value => value - 1)}>Previous</button><button disabled={page * 24 >= catalog.total || catalogLoading} onClick={() => setPage(value => value + 1)}>Next</button></div></div></section>
      </>}
      {section === 'reviews' && <section className="admin-panel"><div className="admin-panel-heading"><div><h2>Uncertain identity matches</h2><p>Review release years, type, and episode identity before merging.</p></div><span className="admin-count">{reviews.length}</span></div>{reviews.length ? <div className="admin-review-list">{reviews.map(review => <div key={review.id}><div><span className="admin-eyebrow">MATCH REVIEW</span><h3>{review.titleName}{review.candidateId ? <><ArrowRight size={16} />{review.candidateName || 'Possible duplicate'}</> : <span className="admin-count">Classification review</span>}</h3><p>{review.reason}</p><small>{date(review.createdAt)}</small></div><div className="admin-row-actions">{review.candidateId && <button disabled={pending !== null || user?.role !== 'admin'} onClick={() => { if (window.confirm(`Merge “${review.titleName}” into “${review.candidateName}”? Confirm these are the same title.`)) perform(review.id, () => api(`/api/admin/reviews/${review.id}`, 'POST', { action: 'merge', targetId: review.candidateId }), 'Match merged.'); }}><Check size={14} />Confirm merge</button>}{!review.candidateId && <button disabled={pending !== null} onClick={() => reviewClassification(review)}>Review classification</button>}<button disabled={pending !== null} onClick={() => { if (review.candidateId || window.confirm(`Publish “${review.titleName}” separately? Review its classification and metadata first. Sources must still pass verification.`)) perform(review.id, () => api(`/api/admin/reviews/${review.id}`, 'POST', { action: 'reject' }), 'Title published separately; source verification still controls public availability.'); }}>{review.candidateId ? 'Keep separate' : 'Publish separately'}</button></div></div>)}</div> : <Empty>Your review queue is clear. Uncertain matches will appear here.</Empty>}</section>}
      {section === 'activity' && <>
        <section className="admin-panel"><div className="admin-panel-heading"><div><h2>Background jobs</h2><p>Worker leases, retries, and durable synchronization reports.</p></div><button className="admin-icon" onClick={loadOverview} aria-label="Refresh jobs"><RefreshCw size={16} /></button></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Job / identifier</th><th>Status</th><th>Started</th><th>Completed</th><th>Result</th></tr></thead><tbody>{jobs.map(job => <tr key={job.id}><td><strong className="capitalize">{job.type.replaceAll('_', ' ')}</strong><small>{job.id.slice(0, 12)}</small></td><td><span className={`admin-job-status ${job.status}`}>{job.status}</span></td><td>{date(job.createdAt)}</td><td>{date(job.completedAt)}</td><td>{job.error ? <span className="admin-inline-error">{job.error}</span> : job.report ? <details><summary>View report</summary><pre>{JSON.stringify(job.report, null, 2)}</pre></details> : 'Awaiting worker result'}</td></tr>)}</tbody></table></div>{!jobs.length && <Empty>No jobs recorded yet.</Empty>}</section>
        <section className="admin-panel admin-audit"><div className="admin-panel-heading"><div><h2>Audit trail</h2><p>Administrative changes are recorded on the server.</p></div></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Action</th><th>Entity</th><th>Actor</th><th>Time</th><th>Details</th></tr></thead><tbody>{(overview?.audit || []).map(entry => <tr key={entry.id}><td><strong>{entry.action.replaceAll('_', ' ')}</strong></td><td>{entry.entityId?.slice(0, 12) || '—'}</td><td>{entry.actorId?.slice(0, 12) || 'System'}</td><td>{date(entry.createdAt)}</td><td>{entry.details ? <details><summary>Inspect</summary><pre>{typeof entry.details === 'string' ? entry.details : JSON.stringify(entry.details, null, 2)}</pre></details> : '—'}</td></tr>)}</tbody></table></div>{!overview?.audit.length && <Empty>No administrative changes recorded.</Empty>}</section>
      </>}
      <footer className="admin-footer"><span>lume control room</span><span>Catalog data · secure sessions · verified availability</span></footer>
    </div></main>
    {toast && <div className="admin-toast" role="status"><Check size={17} />{toast}</div>}
    {importOpen && <ImportDialog onClose={() => setImportOpen(false)} onImport={async rows => {
      setPending('import'); setError('');
      const results = await Promise.allSettled(rows.entries.map(row => api<{ playlist: Playlist; jobId: string }>('/api/admin/playlists', 'POST', { name: row.name, ...(row.content ? { content: row.content } : { url: row.url }), intervalHours: rows.intervalHours, authorized: true })));
      const successfulIds: number[] = [], errors: string[] = [];
      const queued: Record<string, string> = {};
      results.forEach((result, index) => { if (result.status === 'fulfilled') { successfulIds.push(rows.entries[index].id); queued[result.value.playlist.id] = result.value.jobId; } else errors.push(`${rows.entries[index].name}: ${result.reason instanceof Error ? result.reason.message : 'Import failed.'}`); });
      setImportJobs(previous => ({ ...previous, ...queued }));
      await refreshAfterMutation(); setPending(null);
      if (successfulIds.length) { setToast(`${successfulIds.length} ${successfulIds.length === 1 ? 'playlist' : 'playlists'} saved and queued. Track importing, verification, and public visibility below.`); setSection('playlists'); }
      if (!errors.length) setImportOpen(false);
      return { successfulIds, errors };
    }} />}
    {playlistEdit && <PlaylistDialog playlist={playlistEdit} onClose={() => setPlaylistEdit(null)} onSave={async body => { if (await perform('playlist-edit', () => api(`/api/admin/playlists/${playlistEdit.id}`, 'PATCH', body), 'Playlist updated.')) setPlaylistEdit(null); }} />}
    {titleEdit && <TitleDialog initial={titleEdit} catalog={catalog.titles} onClose={() => setTitleEdit(null)} onChanged={async () => { await refreshAfterMutation(); await loadCatalog(); }} notify={setToast} isAdmin={user?.role === 'admin'} />}
    {historyId && <Dialog title="Playlist synchronization history" onClose={() => setHistoryId(null)} wide><PlaylistHistory playlistId={historyId} isAdmin={user?.role === 'admin'} /></Dialog>}
  </div>;
}

function ImportDialog({ onClose, onImport }: { onClose: () => void; onImport: (data: { entries: ImportRow[]; intervalHours: number }) => Promise<{ successfulIds: number[]; errors: string[] }> }) {
  const [rows, setRows] = useState<ImportRow[]>([{ id: 1, name: '', url: '', content: '', fileName: '' }]);
  const [interval, setInterval] = useState('12'); const [custom, setCustom] = useState(6); const [consent, setConsent] = useState(false); const [pending, setPending] = useState(false); const [error, setError] = useState('');
  const update = (id: number, patch: Partial<ImportRow>) => setRows(values => values.map(row => row.id === id ? { ...row, ...patch } : row));
  async function submit(event: React.FormEvent) { event.preventDefault(); setError(''); const hours = interval === 'custom' ? custom : Number(interval); if (!consent) { setError('Confirm that you are authorized to use these sources.'); return; } if (rows.some(row => !row.name.trim() || (!row.url.trim() && !row.content))) { setError('Each playlist needs a name and either a URL or a file.'); return; } if (!Number.isFinite(hours) || hours < 1 || hours > 720) { setError('Choose a refresh interval from 1 to 720 hours.'); return; } setPending(true); try { const result = await onImport({ entries: rows, intervalHours: hours }); if (result.errors.length) { setRows(values => values.filter(row => !result.successfulIds.includes(row.id))); setError(result.errors.join(' ')); } } catch (reason) { setError(reason instanceof Error ? reason.message : 'Import request failed.'); } finally { setPending(false); } }
  return <Dialog title="Connect authorized playlists" onClose={onClose} wide><form onSubmit={submit}><p className="admin-dialog-intro">Add an M3U/M3U8 URL or file. Every stream is checked separately before becoming available to viewers.</p><div className="admin-import-rows">{rows.map((row, index) => <div className="admin-import-row" key={row.id}><div className="admin-import-number">{String(index + 1).padStart(2, '0')}</div><div className="admin-form-grid"><Field label="Playlist name"><input required value={row.name} maxLength={100} onChange={event => update(row.id, { name: event.target.value })} placeholder="e.g. Licensed animation" /></Field><Field label={row.fileName ? 'Uploaded file' : 'M3U playlist URL'}>{row.fileName ? <div className="admin-file-name"><FileUp size={15} />{row.fileName}<button type="button" onClick={() => update(row.id, { content: '', fileName: '' })} aria-label="Remove uploaded file"><X size={14} /></button></div> : <input type="url" value={row.url} onChange={event => update(row.id, { url: event.target.value })} placeholder="https://provider.example/library.m3u" />}</Field><label className="admin-upload"><FileUp size={15} /><span>{row.fileName ? 'Replace file' : 'Upload M3U / M3U8 instead'}</span><input type="file" accept=".m3u,.m3u8,audio/x-mpegurl,application/vnd.apple.mpegurl,text/plain" onChange={async event => { const file = event.target.files?.[0]; if (!file) return; try { update(row.id, { content: await file.text(), fileName: file.name, url: '', ...(!row.name ? { name: file.name.replace(/\.m3u8?$/i, '') } : {}) }); } catch (reason) { setError(reason instanceof Error ? reason.message : 'The playlist file could not be read. Please try again.'); } }} /></label></div>{rows.length > 1 && <button className="admin-icon" type="button" onClick={() => setRows(values => values.filter(value => value.id !== row.id))} aria-label="Remove playlist row"><Trash2 size={15} /></button>}</div>)}</div><button className="admin-text-button" type="button" onClick={() => setRows(values => [...values, { id: Date.now(), name: '', url: '', content: '', fileName: '' }])}><Plus size={14} />Add another playlist</button><div className="admin-form-grid admin-import-settings"><Field label="Refresh interval"><select value={interval} onChange={event => setInterval(event.target.value)}><option value="5">Every 5 hours</option><option value="12">Every 12 hours</option><option value="24">Every 24 hours</option><option value="custom">Custom interval</option></select></Field>{interval === 'custom' && <Field label="Hours (1–720)"><input required type="number" min={1} max={720} value={custom} onChange={event => setCustom(Number(event.target.value))} /></Field>}</div><label className="admin-consent"><input type="checkbox" required checked={consent} onChange={event => setConsent(event.target.checked)} /><span>I have permission to import, access, and distribute the content from these playlists.</span></label>{error && <div className="admin-error" role="alert">{error}</div>}<div className="admin-dialog-actions"><button type="button" className="admin-button" onClick={onClose} disabled={pending}>Cancel</button><button type="submit" className="admin-button primary" disabled={pending}>{pending ? <LoaderCircle className="spin" size={16} /> : <Plus size={16} />}{pending ? 'Adding playlists…' : `Import ${rows.length === 1 ? 'playlist' : `${rows.length} playlists`}`}</button></div></form></Dialog>;
}

function PlaylistDialog({ playlist, onClose, onSave }: { playlist: Playlist; onClose: () => void; onSave: (body: unknown) => Promise<void> }) {
  const [name, setName] = useState(playlist.name); const [hours, setHours] = useState(playlist.intervalHours); const [url, setUrl] = useState(''); const [authorized, setAuthorized] = useState(false); const [enabled, setEnabled] = useState(playlist.enabled); const [pending, setPending] = useState(false);
  return <Dialog title="Edit playlist" onClose={onClose}><form onSubmit={async event => { event.preventDefault(); setPending(true); await onSave({ name, intervalHours: hours, enabled, ...(url ? { url, authorized } : {}) }); setPending(false); }}><div className="admin-form-grid"><Field label="Name" wide><input required value={name} onChange={event => setName(event.target.value)} maxLength={100} /></Field><Field label="Refresh interval (hours)" wide><input type="number" required min={1} max={720} value={hours} onChange={event => setHours(Number(event.target.value))} /></Field><Field label="Replace URL (optional)" wide><input type="url" value={url} onChange={event => setUrl(event.target.value)} placeholder="Leave empty to keep the current source" /></Field></div>{url && <label className="admin-consent"><input type="checkbox" required checked={authorized} onChange={event => setAuthorized(event.target.checked)} /><span>I am authorized to use this replacement URL.</span></label>}<label className="admin-consent"><input type="checkbox" checked={enabled} onChange={event => setEnabled(event.target.checked)} /><span>Enable playlist and automatic synchronization</span></label><div className="admin-dialog-actions"><button className="admin-button" type="button" onClick={onClose}>Cancel</button><button className="admin-button primary" disabled={pending}>{pending && <LoaderCircle className="spin" size={15} />}Save changes</button></div></form></Dialog>;
}

function PlaylistHistory({ playlistId, isAdmin }: { playlistId: string; isAdmin: boolean }) {
  const [history, setHistory] = useState<Record<string, unknown>[]>([]); const [error, setError] = useState(''); const [loading, setLoading] = useState(true); const [pending, setPending] = useState(false); const [message, setMessage] = useState('');
  useEffect(() => { api<{ history: Record<string, unknown>[] }>(`/api/admin/playlists/${playlistId}/history`).then(data => setHistory(data.history)).catch(reason => setError(reason.message)).finally(() => setLoading(false)); }, [playlistId]);
  if (loading) return <div className="admin-loading"><LoaderCircle className="spin" />Loading synchronization history…</div>;
  if (error) return <div className="admin-error" role="alert">{error}</div>;
  return history.length ? <div className="admin-history">{message && <div className="admin-note" role="status">{message}</div>}{history.map((entry, index) => <details key={String(entry.id || index)}><summary>{date(Number(entry.createdAt || entry.syncedAt))} · {String(entry.status || 'Synchronization')}</summary><pre>{JSON.stringify(entry, null, 2)}</pre>{isAdmin && <button className="admin-button compact" disabled={pending} onClick={async () => { if (!window.confirm('Restore this imported snapshot? Current watch progress and metadata will be preserved.')) return; setPending(true); try { await api(`/api/admin/playlists/${playlistId}/restore`, 'POST', { versionId: entry.id }); setMessage('Snapshot recovery queued. Inspect the job result in Activity & jobs.'); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Recovery could not be queued.'); } finally { setPending(false); } }}><HistoryIcon />Restore snapshot</button>}</details>)}</div> : <Empty>No synchronization history recorded for this playlist.</Empty>;
}
function HistoryIcon() { return <RefreshCw size={13} />; }

function TitleDialog({ initial, catalog, onClose, onChanged, notify, isAdmin }: { initial: Title; catalog: Title[]; onClose: () => void; onChanged: () => Promise<void>; notify: (message: string) => void; isAdmin: boolean }) {
  const [title, setTitle] = useState(initial); const [tab, setTab] = useState<'metadata' | 'sources' | 'episodes' | 'identity'>('metadata'); const [error, setError] = useState(''); const [pending, setPending] = useState(false); const [newSource, setNewSource] = useState({ name: '', url: '', episodeId: '', priority: 50 }); const [mergeTarget, setMergeTarget] = useState<Title | null>(null); const [split, setSplit] = useState<{ sourceId: string; name: string; year: string } | null>(null); const [reassign, setReassign] = useState<{ sourceId: string; target: Title | null; episodeId: string } | null>(null); const [episode, setEpisode] = useState<Episode | null>(null);
  const patch = (data: Partial<Title>) => setTitle(value => ({ ...value, ...data }));
  const sources = titleSources(title);
  const [sourceEdit, setSourceEdit] = useState<{ id: string; name: string; url: string; priority: number } | null>(null);
  useEffect(() => {
    if (tab !== 'sources') return;
    const timer = setInterval(async () => { try { const data = await api<CatalogResponse>(`/api/admin/catalog?q=${encodeURIComponent(title.name)}&limit=100`); const fresh = data.titles.find(value => value.id === title.id); if (fresh) setTitle(value => ({ ...value, sources: fresh.sources, episodes: fresh.episodes })); } catch { /* The dashboard surfaces session and connection errors. */ } }, 10000);
    return () => clearInterval(timer);
  }, [tab, title.id, title.name]);
  async function action(request: () => Promise<unknown>, message: string) { setPending(true); setError(''); try { await request(); notify(message); await onChanged(); const data = await api<CatalogResponse>(`/api/admin/catalog?q=${encodeURIComponent(title.name)}`); const next = data.titles.find(value => value.id === title.id); if (next) setTitle(next); return true; } catch (reason) { setError(reason instanceof Error ? reason.message : 'Change failed.'); return false; } finally { setPending(false); } }
  function timestamp(label: string, key: keyof Title) { return <Field label={label}><input type="number" min={0} step="0.1" value={title[key] as number ?? ''} onChange={event => patch({ [key]: event.target.value === '' ? null : Number(event.target.value) } as Partial<Title>)} /></Field>; }
  return <Dialog title={title.name} onClose={onClose} wide><div className="admin-editor-tabs">{(['metadata', 'sources', ...(title.type === 'series' ? ['episodes'] : []), 'identity'] as const).map(value => <button key={value} className={tab === value ? 'active' : ''} onClick={() => setTab(value as typeof tab)}>{value}</button>)}</div>{error && <div className="admin-error" role="alert">{error}</div>}
    {tab === 'metadata' && <form onSubmit={async event => { event.preventDefault(); const { sources: _, episodes: __, ...metadata } = title; await action(() => api(`/api/admin/titles/${title.id}`, 'PATCH', metadata), 'Metadata saved.'); }}><div className="admin-form-grid"><Field label="Title"><input value={title.name} required onChange={event => patch({ name: event.target.value })} /></Field><Field label="Content type"><select value={title.type} onChange={event => patch({ type: event.target.value as Title['type'] })}><option value="movie">Movie</option><option value="series">TV series</option><option value="live">Live channel</option></select></Field><Field label="Synopsis" wide><textarea rows={4} value={title.synopsis} onChange={event => patch({ synopsis: event.target.value })} /></Field><Field label="Release year"><input type="number" min={1880} max={2200} value={title.year || ''} onChange={event => patch({ year: event.target.value ? Number(event.target.value) : null })} /></Field><Field label="Duration (seconds)"><input type="number" min={0} value={title.duration ?? ''} onChange={event => patch({ duration: event.target.value ? Number(event.target.value) : null })} /></Field><Field label="Genres (comma separated)"><input value={title.genres.join(', ')} onChange={event => patch({ genres: event.target.value.split(',').map(value => value.trim()) })} /></Field><Field label="Age rating"><input value={title.ageRating || ''} onChange={event => patch({ ageRating: event.target.value })} placeholder="e.g. PG" /></Field><Field label="Poster URL"><input type="url" value={title.poster} onChange={event => patch({ poster: event.target.value })} /></Field><Field label="Backdrop URL"><input type="url" value={title.backdrop} onChange={event => patch({ backdrop: event.target.value })} /></Field><Field label="Cast (comma separated)"><input value={title.cast.join(', ')} onChange={event => patch({ cast: event.target.value.split(',').map(value => value.trim()) })} /></Field><Field label="Director"><input value={title.director} onChange={event => patch({ director: event.target.value })} /></Field><Field label="Trailer URL" wide><input type="url" value={title.trailer || ''} onChange={event => patch({ trailer: event.target.value })} /></Field><Field label="Credits / license attribution" wide><textarea rows={2} value={title.attribution} onChange={event => patch({ attribution: event.target.value })} /></Field>{timestamp('Intro start (seconds)', 'introStart')}{timestamp('Intro end (seconds)', 'introEnd')}{timestamp('Recap start (seconds)', 'recapStart')}{timestamp('Recap end (seconds)', 'recapEnd')}</div><div className="admin-inline-options"><label><input type="checkbox" checked={title.published} onChange={event => patch({ published: event.target.checked })} />Published</label><label><input type="checkbox" checked={title.featured} onChange={event => patch({ featured: event.target.checked })} />Featured</label><label><input type="checkbox" checked={title.demo} onChange={event => patch({ demo: event.target.checked })} />Sample content label</label></div><p className="admin-help">Changing classification unpublishes the title. Review episode and source assignments before publishing again. Publication also requires an enabled, verified source. Skip timestamps are only used when they form a valid range.</p><div className="admin-dialog-actions"><button className="admin-button primary" disabled={pending}>{pending && <LoaderCircle className="spin" size={15} />}Save metadata</button></div></form>}
    {tab === 'sources' && <><p className="admin-dialog-intro">Higher priority numbers are tried first. Health is assigned by verified checks. Private provider credentials require the playback signing integration.</p><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Source</th><th>Format / quality</th><th>Health</th><th>Last check / success / failure</th><th>Priority</th><th>Actions</th></tr></thead><tbody>{sources.map(source => <tr key={source.id}><td><strong>{source.name}</strong><small>{source.id.slice(0, 10)}{source.episodeId ? ' · Episode source' : ''}</small>{source.error && <span className="admin-inline-error">{source.error}</span>}</td><td className="capitalize">{source.format}<small>{source.quality || 'Quality not verified'}</small></td><td><HealthBadge health={source.health} /></td><td>{date(source.lastChecked)}<small>Success: {date(source.lastSuccess)}</small><small>Failure: {date(source.lastFailure)}</small></td><td><input className="admin-priority" aria-label={`Priority for ${source.name}`} type="number" min={0} max={999} defaultValue={source.priority} onBlur={event => { const priority = Number(event.target.value); if (priority !== source.priority) action(() => api(`/api/admin/sources/${source.id}`, 'PATCH', { priority }), 'Source priority updated.'); }} /></td><td><div className="admin-row-actions"><button disabled={pending} onClick={() => action(() => api(`/api/admin/sources/${source.id}/check`, 'POST'), 'Source verification queued.')}><RefreshCw size={13} />Check</button><button disabled={pending} onClick={() => action(() => api(`/api/admin/sources/${source.id}`, 'PATCH', { enabled: !source.enabled }), source.enabled ? 'Source disabled.' : 'Source enabled.')}>{source.enabled ? 'Disable' : 'Enable'}</button><button onClick={() => setSourceEdit({ id: source.id, name: source.name, url: '', priority: source.priority })}>Edit</button><button disabled={!isAdmin || pending} title={!isAdmin ? 'Administrator role required' : 'Move source'} onClick={() => setReassign({ sourceId: source.id, target: title, episodeId: source.episodeId || '' })}>Move</button><button disabled={!isAdmin || pending} title={!isAdmin ? 'Administrator role required' : 'Split source'} onClick={() => setSplit({ sourceId: source.id, name: '', year: '' })}>Split</button><button className="danger" aria-label={`Remove ${source.name}`} disabled={pending || !isAdmin} onClick={() => { if (window.confirm(`Remove source “${source.name}”?`)) action(() => api(`/api/admin/sources/${source.id}`, 'DELETE'), 'Source removed.'); }}><Trash2 size={13} /></button></div></td></tr>)}</tbody></table></div>{!sources.length && <Empty>No streaming sources attached.</Empty>}<form className="admin-add-source" onSubmit={async event => { event.preventDefault(); if (await action(() => api('/api/admin/sources', 'POST', { titleId: title.id, ...newSource, episodeId: newSource.episodeId || null }), 'Source added and queued for verification.')) setNewSource({ name: '', url: '', episodeId: '', priority: 50 }); }}><h3>Add a source</h3><div className="admin-form-grid"><Field label="Server name"><input required value={newSource.name} onChange={event => setNewSource(value => ({ ...value, name: event.target.value }))} placeholder="Authorized server" /></Field><Field label="Video / HLS / DASH URL"><input required type="url" value={newSource.url} onChange={event => setNewSource(value => ({ ...value, url: event.target.value }))} placeholder="https://…" /></Field>{title.type === 'series' && <Field label="Episode"><select required value={newSource.episodeId} onChange={event => setNewSource(value => ({ ...value, episodeId: event.target.value }))}><option value="">Select episode</option>{title.episodes?.map(value => <option key={value.id} value={value.id}>S{value.season} E{value.number} — {value.name}</option>)}</select></Field>}<Field label="Priority"><input type="number" min={0} max={999} value={newSource.priority} onChange={event => setNewSource(value => ({ ...value, priority: Number(event.target.value) }))} /></Field></div><label className="admin-consent"><input type="checkbox" required /><span>I am authorized to stream this content.</span></label><button className="admin-button primary" disabled={pending}><Plus size={15} />Add source</button></form></>}
    {tab === 'episodes' && <div className="admin-episode-list"><button className="admin-button primary" onClick={() => setEpisode({ id: '', titleId: title.id, season: 1, number: (title.episodes?.length || 0) + 1, name: '', duration: null, available: false })}><Plus size={14} />Add episode</button>{title.episodes?.map(value => <div key={value.id}><div><span className="admin-episode-number">S{String(value.season).padStart(2, '0')} · E{String(value.number).padStart(2, '0')}</span><strong>{value.name}</strong><small>{value.duration ? `${Math.round(value.duration / 60)} min` : 'Duration unknown'} · {value.available ? 'Available' : 'Unavailable'}</small></div><div className="admin-row-actions"><button className="admin-button compact" onClick={() => setEpisode(value)}>Edit episode</button><button disabled={!isAdmin || pending} className="danger" aria-label={`Remove episode ${value.number}`} onClick={() => { if (window.confirm(`Remove S${value.season} E${value.number} and its sources?`)) action(() => api(`/api/admin/episodes/${value.id}`, 'DELETE'), 'Episode removed.'); }}><Trash2 size={14} /></button></div></div>)}{!title.episodes?.length && <Empty>No episodes imported. Import an authorized playlist with season and episode identifiers.</Empty>}</div>}
    {tab === 'identity' && <form onSubmit={async event => { event.preventDefault(); if (window.confirm(`Merge “${title.name}” into the selected title? Sources and saved progress will move to the target.`)) { if (await action(() => api('/api/admin/titles/merge', 'POST', { fromId: title.id, toId: mergeTarget?.id }), 'Titles merged.')) onClose(); } }}><div className="admin-note"><CircleAlert size={18} /><div><strong>Confirm identity before merging.</strong><p>Match the release year, content type, and episode identity. Remakes and similarly named films should remain separate.</p></div></div><AdminTitlePicker label="Merge into title" value={mergeTarget} onChange={setMergeTarget} initialTitles={catalog} excludeId={title.id} contentType={title.type} disabled={pending} /><p className="admin-help">Sources and saved progress will move into the selected title.</p><button className="admin-button primary" disabled={pending || !mergeTarget || !isAdmin}>Merge into target <ArrowRight size={15} /></button><p className="admin-help">To undo an incorrect source grouping, open Sources and choose Split or Move beside the source.</p></form>}
    {sourceEdit && <div className="admin-nested-dialog"><form onSubmit={async event => { event.preventDefault(); if (await action(() => api(`/api/admin/sources/${sourceEdit.id}`, 'PATCH', { name: sourceEdit.name, priority: sourceEdit.priority, ...(sourceEdit.url ? { url: sourceEdit.url } : {}) }), 'Source updated. Changed URLs are queued for verification.')) setSourceEdit(null); }}><h3>Edit streaming source</h3><div className="admin-form-grid"><Field label="Server name"><input required value={sourceEdit.name} onChange={event => setSourceEdit(value => value && ({ ...value, name: event.target.value }))} /></Field><Field label="Priority"><input type="number" min={-1000} max={1000} value={sourceEdit.priority} onChange={event => setSourceEdit(value => value && ({ ...value, priority: Number(event.target.value) }))} /></Field><Field label="Replacement source URL (optional)" wide><input type="url" value={sourceEdit.url} onChange={event => setSourceEdit(value => value && ({ ...value, url: event.target.value }))} placeholder="Leave empty to retain the current URL" /></Field></div>{sourceEdit.url && <label className="admin-consent"><input required type="checkbox" /><span>I am authorized to stream the content at this replacement URL.</span></label>}<div className="admin-dialog-actions"><button type="button" className="admin-button" onClick={() => setSourceEdit(null)}>Cancel</button><button className="admin-button primary" disabled={pending}>Save source</button></div></form></div>}
    {split && <div className="admin-nested-dialog"><form onSubmit={async event => { event.preventDefault(); if (await action(() => api(`/api/admin/sources/${split.sourceId}/split`, 'POST', { name: split.name, year: split.year ? Number(split.year) : null }), 'Source split into a separate title.')) setSplit(null); }}><h3>Split source into a new title</h3><div className="admin-form-grid"><Field label="New title name"><input required value={split.name} onChange={event => setSplit(value => value && ({ ...value, name: event.target.value }))} /></Field><Field label="Release year"><input type="number" min={1880} max={2200} value={split.year} onChange={event => setSplit(value => value && ({ ...value, year: event.target.value }))} /></Field></div><div className="admin-dialog-actions"><button type="button" className="admin-button" onClick={() => setSplit(null)}>Cancel</button><button className="admin-button primary" disabled={pending}>Split source</button></div></form></div>}
    {reassign && <div className="admin-nested-dialog"><form onSubmit={async event => { event.preventDefault(); if (await action(() => api(`/api/admin/sources/${reassign.sourceId}`, 'PATCH', { titleId: reassign.target?.id, episodeId: reassign.episodeId || null }), 'Source moved.')) setReassign(null); }}><h3>Assign source to a title or episode</h3><AdminTitlePicker label="Destination title" value={reassign.target} onChange={target => setReassign(value => value && ({ ...value, target, episodeId: '' }))} initialTitles={catalog} disabled={pending} />{reassign.target?.type === 'series' && <Field label="Destination episode"><select required value={reassign.episodeId} onChange={event => setReassign(value => value && ({ ...value, episodeId: event.target.value }))}><option value="">Choose an episode</option>{reassign.target.episodes?.map(value => <option key={value.id} value={value.id}>Season {value.season} · Episode {value.number} — {value.name}</option>)}</select></Field>}{reassign.target?.type === 'series' && !reassign.target.episodes?.length && <p className="admin-help">This series has no episodes yet. Create an episode in its catalog editor before assigning a source.</p>}<div className="admin-dialog-actions"><button type="button" className="admin-button" onClick={() => setReassign(null)}>Cancel</button><button className="admin-button primary" disabled={pending || !reassign.target || (reassign.target.type === 'series' && !reassign.episodeId)}>Move source</button></div></form></div>}
    {episode && <div className="admin-nested-dialog"><form onSubmit={async event => { event.preventDefault(); if (await action(() => api(episode.id ? `/api/admin/episodes/${episode.id}` : '/api/admin/episodes', episode.id ? 'PATCH' : 'POST', episode), 'Episode updated.')) setEpisode(null); }}><h3>{episode.id ? 'Edit episode' : 'Add episode'}</h3><div className="admin-form-grid"><Field label="Episode name" wide><input required value={episode.name} onChange={event => setEpisode(value => value && ({ ...value, name: event.target.value }))} /></Field>{(['season', 'number', 'duration', 'introStart', 'introEnd', 'recapStart', 'recapEnd'] as const).map(key => <Field key={key} label={key === 'number' ? 'Episode number' : key.replace(/([A-Z])/g, ' $1').replace(/^./, value => value.toUpperCase()) + (['duration', 'introStart', 'introEnd', 'recapStart', 'recapEnd'].includes(key) ? ' (seconds)' : '')}><input type="number" min={key === 'season' || key === 'number' ? 1 : 0} value={episode[key] ?? ''} onChange={event => setEpisode(value => value && ({ ...value, [key]: event.target.value ? Number(event.target.value) : null }))} /></Field>)}</div><div className="admin-dialog-actions"><button type="button" className="admin-button" onClick={() => setEpisode(null)}>Cancel</button><button className="admin-button primary" disabled={pending}>Save episode</button></div></form></div>}
  </Dialog>;
}
